WITH filtered AS (SELECT *, status_bits * humidity AS status_bits_times_humidity FROM device_readings WHERE reading_ts >= TIMESTAMP '2025-09-01 09:00:00'), with_gaps AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL '45' MINUTE THEN 1 ELSE 0 END AS session_start_flag FROM filtered), sessions_device_readings AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT CASE WHEN temp_c >= 34 THEN 'LARGE' ELSE 'SMALL' END AS temp_c_tier, COUNT(*) FILTER (WHERE device_code = 'DV-01') AS dv_01_rows, SORT_ARRAY(COLLECT_SET(device_code)) AS device_code_list, SUM(CASE WHEN device_code = 'DV-02' THEN session_start_flag ELSE 0 END) AS dv_02_session_start_flag, MIN(reading_ts) AS first_seen FROM sessions_device_readings GROUP BY CASE WHEN temp_c >= 34 THEN 'LARGE' ELSE 'SMALL' END;
